import csv
import io
import json
import zipfile
from pathlib import Path

INPUT_PATH = Path("inputs/gtfs/sample_city_gtfs.zip")
OUTPUT_PATH = Path("outputs/t04_gtfs_summary.json")

FILES = ("stops", "routes", "trips", "stop_times")
FILENAMES = {key: key + ".txt" for key in FILES}
HEADER_HINTS = {...}

def find_member(zf, filename):
    names = zf.namelist()
    for name in names:
        if name == filename:
            return name
    direct = [name for name in names if name.endswith("/" + filename)]
    if direct:
        return min(direct, key=lambda x: (x.count("/"), x))
    lower_filename = filename.lower()
    for name in names:
        if name.lower() == lower_filename:
            return name
    direct_lower = [name for name in names if name.lower().endswith("/" + lower_filename)]
    if direct_lower:
        return min(direct_lower, key=lambda x: (x.count("/"), x))
    return None

def looks_like_header(key, row):
    if not row:
        return False
    cells = set()
    for cell in row:
        if cell is not None:
            cells.add(cell.strip().lower())
    hints = HEADER_HINTS.get(key, set())
    return any(hint in cells for hint in hints)

def count_rows(zf, member, key):
    try:
        with zf.open(member) as raw:
            text = io.TextIOWrapper(raw, encoding="utf-8-sig", newline="")
            try:
                reader = csv.reader(text)
                count = 0
                seen_first = False
                for row in reader:
                    if not row:
                        continue
                    if not seen_first:
                        seen_first = True
                        if looks_like_header(key, row):
                            continue
                        count = 1
                    else:
                        count += 1
                return count
            finally:
                text.close()
    except Exception:
        return 0

